// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.LmdbCompatibilityFixtures.extract;
import static org.eclipse.rdf4j.sail.lmdb.LmdbCompatibilityFixtures.snapshot;
import static org.eclipse.rdf4j.sail.lmdb.LmdbLegacyIndexDiscoveryTest.createNamedDatabase;
import static org.eclipse.rdf4j.sail.lmdb.LmdbLegacyIndexDiscoveryTest.nativeDeleteTriple;
import static org.eclipse.rdf4j.sail.lmdb.LmdbLegacyIndexDiscoveryTest.readNativeKeys;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Path;
import java.util.List;

import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The format-2 preflight sweeps over the dictionary and statement indexes are opt-in. A versioned legacy store opens
 * with the default configuration without walking its indexes; {@code legacyStoreValidationEnabled} restores the sweeps.
 * The cheap catalog checks and the one-time validation of an unversioned 6.1.x store are not gated.
 */
class LmdbLegacyStoreValidationOptInTest {

	private static final String SECONDARY_STATEMENT_INDEX = TripleIndex.nativeDatabaseName("posc", true);

	@TempDir
	Path directory;

	@Test
	void defaultConfigOpensVersionedLegacyStoreWithInconsistentStatementIndex() throws Exception {
		extract("v2-610-default.zip", directory);
		assertThat(LmdbCompatibilityFixtures.properties(directory, "store.properties").getProperty("version"))
				.isEqualTo("2");
		removeOneSecondaryIndexRow();

		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), defaultConfig()));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertThat(connection.size()).isEqualTo(4);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void enabledValidationRefusesInconsistentVersionedLegacyStoreWithoutMutation() throws Exception {
		extract("v2-610-default.zip", directory);
		removeOneSecondaryIndexRow();

		assertRefusedWithoutMutation(defaultConfig().setLegacyStoreValidationEnabled(true),
				"Statement index entry counts disagree");
	}

	@Test
	void enabledValidationOpensConsistentVersionedLegacyStore() throws Exception {
		extract("v2-610-default.zip", directory);

		SailRepository repository = new SailRepository(
				new LmdbStore(directory.toFile(), defaultConfig().setLegacyStoreValidationEnabled(true)));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertThat(connection.size()).isEqualTo(4);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void defaultConfigStillRejectsUnknownNamedDatabaseWithoutMutation() throws Exception {
		extract("v2-610-default.zip", directory);
		createNamedDatabase(directory.resolve("triples"), "future-index");

		assertRefusedWithoutMutation(defaultConfig(), "Unrecognized named database in triples environment");
	}

	@Test
	void defaultConfigStillValidatesUnversionedLegacyStoreBeforeRecordingDescriptors() throws Exception {
		extract("v2-unpatched-legacy.zip", directory);
		assertThat(directory.resolve("store.properties")).doesNotExist();

		assertRefusedWithoutMutation(defaultConfig(), "Statement index entry counts disagree");
		assertThat(directory.resolve("store.properties")).doesNotExist();
	}

	private void removeOneSecondaryIndexRow() throws Exception {
		List<byte[]> rows = readNativeKeys(directory.resolve("triples"), SECONDARY_STATEMENT_INDEX);
		assertThat(rows).hasSize(4);
		nativeDeleteTriple(directory.resolve("triples"), SECONDARY_STATEMENT_INDEX, rows.get(0));
		assertThat(LmdbCompatibilityFixtures.nativeTripleEntryCount(directory, SECONDARY_STATEMENT_INDEX))
				.isEqualTo(3);
		assertThat(LmdbCompatibilityFixtures.nativeTripleEntryCount(directory,
				TripleIndex.nativeDatabaseName("spoc", true))).isEqualTo(4);
	}

	private void assertRefusedWithoutMutation(LmdbStoreConfig config, String expectedRootMessage) throws Exception {
		var before = snapshot(directory);
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			RuntimeException failure = assertThrows(RuntimeException.class, repository::init);
			assertThat(failure).rootCause().hasMessageContaining(expectedRootMessage);
		} finally {
			repository.shutDown();
		}
		assertThat(snapshot(directory)).isEqualTo(before);
	}

	private static LmdbStoreConfig defaultConfig() {
		return new LmdbStoreConfig().setInlineLiterals(false);
	}
}
